package com.ray.controller;
import com.ray.result.Result;import com.ray.service.*;import com.ray.utils.converter.IdUtils;import com.ray.vo.*;import io.swagger.v3.oas.annotations.Operation;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import org.springframework.http.MediaType;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;
@RestController @SecurityRequirement(name="BearerAuth") @Tag(name="实时事件与动态二维码") public class RealtimeEventController {private final VoucherQrTokenService qr;private final EventTicketService tickets;private final AdminAuthService admin;public RealtimeEventController(VoucherQrTokenService qr,EventTicketService tickets,AdminAuthService admin){this.qr=qr;this.tickets=tickets;this.admin=admin;}
 @PostMapping("/v1/users/me/vouchers/{voucherId}/qr-tokens") @Operation(summary="生成动态券二维码",operationId="issueVoucherQrToken") public Result<VoucherQrTokenVO> qr(@PathVariable String voucherId){return Result.ok(qr.issue(IdUtils.parse(voucherId,"voucherId")));}
 @PostMapping("/v1/admin/event-tickets") @Operation(summary="申请管理事件票据",operationId="issueAdminEventTicket") public Result<AdminEventTicketVO> ticket(){return Result.ok(tickets.issue());}
 @GetMapping(value="/v1/admin/events",produces=MediaType.TEXT_EVENT_STREAM_VALUE) @Operation(summary="订阅管理事件",operationId="subscribeAdminEvents") public SseEmitter events(@RequestParam String ticket){admin.currentAdmin();if(!tickets.valid(ticket)){throw com.ray.exception.BusinessException.forbidden("EVENT_TICKET_INVALID","事件票据无效或已过期");}SseEmitter emitter=new SseEmitter(30000L);try{emitter.send(SseEmitter.event().name("connected").data("{\"type\":\"CONNECTED\"}"));}catch(Exception e){emitter.completeWithError(e);}return emitter;}
}
